function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const grid = $('GET meetings values').first().json.values || [];
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

// --- meetings (latest staircase block) ---
function isHdr(row) { return /startup got meetings/i.test(s((row || [])[1])) && /\d/.test(s((row || [])[0])); }
const hdrs = []; for (let i = 0; i < grid.length; i++) { if (isHdr(grid[i])) { hdrs.push(i); } }
const TODAYD = new Date(Date.UTC(2026, 8, 11));
function blockDate(label) { const m = s(label).match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/); if (!m) { return null; }
  const a = +m[1], b = +m[2], y = +m[3]; const c = [];
  if (b >= 1 && b <= 12 && a >= 1 && a <= 31) { c.push(new Date(Date.UTC(y, b - 1, a))); }
  if (a >= 1 && a <= 12 && b >= 1 && b <= 31) { c.push(new Date(Date.UTC(y, a - 1, b))); }
  const past = c.filter(function (d) { return d <= TODAYD; }); const pool = past.length ? past : c;
  pool.sort(function (x, z) { return z - x; }); return pool[0] || null; }
let li = hdrs[hdrs.length - 1]; let ld = blockDate(s(grid[li][0]));
for (const i of hdrs) { const d = blockDate(s(grid[i][0])); if (d && (!ld || d > ld)) { ld = d; li = i; } }
const stair = {};
for (let i = li + 1; i < grid.length; i++) { const row = grid[i] || []; if (isHdr(row)) { break; }
  const m = s(row[1]).match(/^(\d+)\s*meetings?/i); if (!m) { if (Object.keys(stair).length) { break; } else { continue; } }
  const n = parseInt(m[1], 10);
  for (let j = 2; j < row.length; j++) { const nm = s(row[j]); if (!nm) { continue; } const k = nz(nm); if (stair[k] === undefined || n > stair[k]) { stair[k] = n; } } }
const ALIAS = { caffeinacoffee: 'caffenacoffee' };
function meetingsFor(name) { const k = nz(name); let best = null;
  for (const sk of Object.keys(stair)) { const kk = ALIAS[sk] || sk;
    const hit = kk === k || (kk.length >= 4 && k.length >= 4 && (kk.indexOf(k) === 0 || k.indexOf(kk) === 0));
    if (hit && (best === null || stair[sk] > best)) { best = stair[sk]; } }
  return best === null ? 0 : best; }

// --- current scoring (same as the tiered rules) ---
const TAGS = [
  ['health', /health|medtech|bio|clinic|pharma|life science|wellness|fitness|diagnost|hospital|patient|doctor/],
  ['fintech', /fintech|lending|insur|payment|banking|wealth|credit|financial|neobank/],
  ['saas', /saas|b2b|enterprise|software|platform|api|devtool|cloud|workflow|automation/],
  ['consumer', /consumer|d2c|b2c|retail|fmcg|food|beverage|fashion|beauty|apparel|coffee|restaurant|cafe|grocer|kitchen|snack|personal care/],
  ['deeptech', /deeptech|deep tech|\bai\b|artificial intelligence|\bml\b|robot|iot|semiconductor|space|drone|quantum|computer vision|hardware/],
  ['climate', /climate|clean|energy|solar|ev\b|electric vehicle|sustain|green|water|waste|carbon|recycl/],
  ['edtech', /edtech|education|learning|skill|training|exam|student|course/],
  ['logistics', /logistic|supply chain|mobility|delivery|freight|shipping|transport|warehous/],
  ['agritech', /agri|farm|agtech|crop/],
  ['hrtech', /hrtech|\bhr\b|recruit|talent|hiring|staffing|workforce/],
  ['proptech', /proptech|real estate|construction|coworking|interior|windoor|building/],
  ['media', /media|gaming|content|entertainment|creator|social|dating|travel|music|video/]
];
function tagsOf(txt) { const t = s(txt).toLowerCase(); const o = {}; for (const p of TAGS) { if (p[1].test(t)) { o[p[0]] = 1; } } return Object.keys(o); }
function startupStage(txt) { const t = s(txt).toLowerCase();
  if (/series[\s-]*[b-e]\b|growth|pre-?\s*ipo/.test(t)) { return 4; }
  if (/series[\s-]*a\b/.test(t)) { return 3; }
  if (/pilot|traction|early revenue|revenue|mvp|launched/.test(t)) { return 2; }
  if (/\bseed\b/.test(t.replace(/pre-?\s*seed/g, ''))) { return 1; }
  if (/pre-?\s*seed|ideation|concept|idea|prototype/.test(t)) { return 0; }
  return 1; }
function investorBand(txt) { const t = s(txt).toLowerCase(); const h = [];
  if (/pre-?\s*seed|preseed/.test(t)) { h.push(0); }
  if (/\bseed\b/.test(t.replace(/pre-?\s*seed/g, ''))) { h.push(1); }
  if (/pilot|traction|early|pre-?\s*series[\s-]*a/.test(t)) { h.push(2); }
  if (/series[\s-]*a\b/.test(t)) { h.push(3); }
  if (/series[\s-]*[b-e]\b|series[\s-]*a\s*[\/&,]\s*b|growth|late|pre-?\s*ipo|onwards|and above/.test(t)) { h.push(4); }
  if (!h.length) { return null; }
  return { lo: Math.min.apply(null, h), hi: Math.max.apply(null, h), seed: h.indexOf(1) >= 0 }; }
function chequeMin(txt) { const t = s(txt).replace(/,/g, '').toLowerCase(); if (!t) { return null; }
  const usd = /\$|usd/.test(t); const re = /(\d+(?:\.\d+)?)\s*(crores?|cr|million|mn|m|k|lakhs?|lacs?)?(?![a-z])/g;
  const tok = []; let m; while ((m = re.exec(t)) !== null) { tok.push({ v: parseFloat(m[1]), u: m[2] || '' }); }
  if (!tok.length) { return null; }
  for (let i = tok.length - 2; i >= 0; i--) { if (!tok[i].u && tok[i + 1].u) { tok[i].u = tok[i + 1].u; } }
  const vals = [];
  for (const k of tok) { const u = k.u || (usd ? 'm' : 'cr'); let cr;
    if (/^cr/.test(u)) { cr = k.v; } else if (/^la/.test(u)) { cr = k.v / 100; }
    else if (u === 'k') { cr = usd ? k.v * 0.0085 : k.v / 10000; } else { cr = usd ? k.v * 8.5 : k.v / 10; }
    if (cr > 0) { vals.push(cr); } }
  if (!vals.length) { return null; }
  if (vals.length === 1 && /up\s*to|upto|\bmax/.test(t)) { return 0; }
  return Math.min.apply(null, vals); }
function raiseOf(txt) { const t = s(txt).replace(/,/g, ''); if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i); if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i); if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i); if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i); if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i); if (m) { return parseFloat(m[1]) / 100; }
  return null; }
const FLOOR_FIX = { a2dventures: 0.85, mintvc: 0.5, pipersireca: 1.0 };
const byName = {};
for (const r of invRaw) { const n = s(r.investor); if (!n) { continue; } const k = nz(n); if (!byName[k]) { byName[k] = []; } byName[k].push(r); }
const inv = {};
for (const k of Object.keys(byName)) { const rs = byName[k]; const pick = rs.filter(function (r) { return s(r.stage) !== ''; })[0] || rs[0];
  let floor = chequeMin(pick.cheque_inr_cr); if (FLOOR_FIX[k] !== undefined) { floor = FLOOR_FIX[k]; }
  inv[k] = { agnostic: /agno/i.test(s(pick.sector)), tags: tagsOf(pick.sector), band: investorBand(pick.stage), floor: floor }; }
const ST = {};
for (const r of stRaw) { const n = s(r.startup); if (!n) { continue; } const mt = meetingsFor(n);
  ST[nz(n)] = { tags: tagsOf(r.sector), si: startupStage(r.stage), raise: raiseOf(r.raise_inr_cr), under5: mt < 5 }; }
function rescore(p) { const st = ST[nz(p.startup)], b = inv[nz(p.investor)]; if (!st || !b || !b.band) { return null; }
  let ov = false; for (const tg of b.tags) { if (st.tags.indexOf(tg) >= 0) { ov = true; break; } }
  const sec = b.agnostic || ov; const chq = b.floor === null || (st.raise !== null && st.raise >= b.floor);
  let stage = 'off'; if (st.si >= b.band.lo && st.si <= b.band.hi) { stage = 'in'; } else if (st.si >= 3 && b.band.seed) { stage = 'in'; }
  else if (st.si === b.band.lo - 1 || st.si === b.band.hi + 1) { stage = 'adjacent'; }
  const ok = sec && chq && (stage === 'in' || (st.under5 && stage === 'adjacent'));
  return { ok: ok, score: (sec ? (ov ? 40 : 28) : 0) + (stage === 'in' ? 30 : (stage === 'adjacent' ? 20 : 0)) + (chq ? (b.floor === null ? 20 : 30) : 0) }; }

// --- the low-priority rows ---
function status(p) { if (s(p.deal_shared).toLowerCase() === 'yes') { return 'sent'; }
  if (s(p.pause).toLowerCase() === 'yes') { const n = s(p.notes);
    if (n.indexOf('ON HOLD 2026-09-10') >= 0) { return 'paused: stage-missing hold'; }
    if (n.indexOf('tier rule') >= 0) { return 'paused: fails tiered rules'; }
    if (n.indexOf('name not found') >= 0) { return 'paused: name not in INVESTORS'; }
    if (n.indexOf('email missing') >= 0) { return 'paused: email missing'; }
    return 'paused: other (older pause)'; }
  return 'QUEUED - will send'; }
function label(p) { const m = s(p.notes).match(/^(Very High|High|Moderate|Low|Strict|Meeting-push)/i); return m ? m[1] : (s(p.notes) ? 'other note' : 'no note'); }
function bucket(id) { const n = parseInt(s(id).slice(1), 10); if (isNaN(n)) { return 'no id'; } if (n < 1000) { return 'D0000-D0999 (first batch)'; } if (n < 2000) { return 'D1000-D1999'; } if (n < 3000) { return 'D2000-D2999'; } return 'D3000+ (9-10 Sep adds)'; }
const low = pipe.filter(function (p) { const v = parseFloat(s(p.priority)); return !isNaN(v) && v < 50; });
const blankPri = pipe.filter(function (p) { return s(p.priority) === ''; }).length;
const byStatus = {}, byLabel = {}, byBucket = {}, hist = {};
const queuedLow = []; let sentReplied = 0, sentPositive = 0, sentN = 0;
for (const p of low) {
  const st = status(p); byStatus[st] = (byStatus[st] || 0) + 1;
  const lb = label(p); byLabel[lb] = (byLabel[lb] || 0) + 1;
  const bk = bucket(p.deal_id); byBucket[bk] = (byBucket[bk] || 0) + 1;
  const v = parseFloat(s(p.priority)); const h = v < 10 ? '0-9' : v < 20 ? '10-19' : v < 30 ? '20-29' : v < 40 ? '30-39' : '40-49'; hist[h] = (hist[h] || 0) + 1;
  if (st === 'sent') { sentN++; const r = s(p.investor_response).toLowerCase(); if (r) { sentReplied++; } if (/interest|intrest|meet|form|question|transfer/.test(r) || s(p.meeting_date)) { sentPositive++; } }
  if (st.indexOf('QUEUED') === 0) { queuedLow.push(p); }
}
// queued low-priority rows: what would today's rules score them?
const requeue = { passes_rules_now: 0, fails_rules_now: 0, cannot_score: 0 }; const newScoreHist = {};
const examples = [];
for (const p of queuedLow) { const r = rescore(p);
  if (!r) { requeue.cannot_score++; } else { if (r.ok) { requeue.passes_rules_now++; } else { requeue.fails_rules_now++; }
    const k = r.score >= 85 ? '85+' : r.score >= 70 ? '70-84' : r.score >= 60 ? '60-69' : '<60'; newScoreHist[k] = (newScoreHist[k] || 0) + 1; }
  if (examples.length < 12) { examples.push([s(p.deal_id), s(p.startup), s(p.investor), s(p.priority), r ? r.score : null, r ? r.ok : null, s(p.next_due), s(p.notes).slice(0, 40)]); } }
// overall sent performance for comparison
let allSent = 0, allRep = 0, allPos = 0;
for (const p of pipe) { if (s(p.deal_shared).toLowerCase() !== 'yes') { continue; } allSent++; const r = s(p.investor_response).toLowerCase(); if (r) { allRep++; } if (/interest|intrest|meet|form|question|transfer/.test(r) || s(p.meeting_date)) { allPos++; } }
return [{ json: { pipeline_rows: pipe.length, priority_under_50: low.length, priority_blank: blankPri,
  by_status: byStatus, by_note_label: byLabel, by_deal_id_batch: byBucket, priority_histogram: hist,
  queued_low_priority: queuedLow.length, queued_low_rescored_today: requeue, queued_low_new_score_bands: newScoreHist,
  sent_low: { sent: sentN, replied: sentReplied, positive: sentPositive }, sent_all: { sent: allSent, replied: allRep, positive: allPos },
  queued_examples_cols: ['deal_id', 'startup', 'investor', 'old_priority', 'score_today', 'passes_rules_today', 'next_due', 'notes'], queued_examples: examples } }];
